INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-910-UND-01', 'English Literacy', 'understanding', '9-10', 'standard', '"The biographer does not romanticize the statesman''s triumphs; rather, she dissects his compromises with the forensic detachment of an anatomist." What characterizes the biographer''s intellectual style?', '[{"text":"Unsentimental, rigorous, and analytically critical examination.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Hagiographic celebration of patriotic martyrdom.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Superficial sensationalism focused on court intrigue.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Nostalgic praise for obsolete diplomatic conventions.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing tone, register, and authorial detachment in high-level biographical prose.', 'Notice words like "forensic detachment" and "dissects compromises".', 1.3, 0.3, 0.25, true, 0, 'IGCSE English Language / Cambridge O-Level'),
('ENG-910-UND-02', 'English Literacy', 'understanding', '9-10', 'standard', '"The judicial majority held that freedom of expression is not an absolute sovereign license, but a situated right bounded by the state''s compelling interest in preventing imminent incitement to violence." How does the court define the boundary of free speech?', '[{"text":"As an unlimited personal entitlement that supersedes all public safety laws.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As a vital but conditional right that may be curtailed when speech creates an immediate threat of unlawful violence.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"As a privilege granted exclusively to licensed journalistic media organizations.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As an obsolete constitutional principle that has no modern relevance.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing complex constitutional legal prose and conditional rights.', 'Look for the boundary: "bounded by the state''s compelling interest in preventing imminent incitement".', 1.35, 0.4, 0.25, true, 0, 'ICSE Class 10 English Language'),
('ENG-910-UND-03', 'English Literacy', 'understanding', '9-10', 'standard', '"In describing the sprawling megalopolis as ''a voracious metabolic engine ingesting rivers of freshwater and exhaling plumes of toxic carbon,'' what ecological paradigm is the author deploying?"', '[{"text":"A celebration of urban architectural density and civil engineering mastery.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"An industrial metabolism paradigm, framing the modern city as an organism with consumptive and excretory resource flows.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A literal claim that asphalt highways possess biological lungs.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A historical economic treatise on pre-industrial river transportation.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting ecological paradigms and metabolic metaphors in urban studies essays.', 'Notice: ingesting freshwater, exhaling carbon, "metabolic engine".', 1.4, 0.5, 0.25, true, 0, 'Singapore MOE Secondary 4 O-Level English'),
('ENG-910-UND-04', 'English Literacy', 'understanding', '9-10', 'standard', '"The novel''s narrator maintains an ironic distance, recounting his family''s catastrophic bankruptcy with the dry amusement of a spectator watching a badly rehearsed farce." What does this tonal dissonance signify?', '[{"text":"Genuine financial joy at being liberated from material wealth.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A psychological coping defense: using cynical levity to shield himself from the raw trauma of domestic ruin.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Total ignorance regarding the reality of debt and insolvency.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A technical theatrical critique of amateur stage productions.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing tonal dissonance as a psychological coping mechanism in first-person narrative.', 'Why would someone narrate their own ruin like it''s a "badly rehearsed farce"?', 1.35, 0.4, 0.25, true, 0, 'US Common Core Grade 10 Reading Literature'),
('ENG-910-UND-05', 'English Literacy', 'understanding', '9-10', 'standard', '"The epistemologist cautioned that our intuitive perception of time as an unbroken flowing river is an evolutionary cognitive convenience, not an ontological feature of physical space-time." What distinction is being drawn?', '[{"text":"Between ancient mythological rivers and modern navigational canals.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Between liquid hydrological flows and mechanical clock escapements.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Between the brain''s adaptive subjective experience of time and the actual mathematical reality of the physical universe.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Between human memory capacity and computer hard drive storage.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Distinguishing ontological reality from evolutionary cognitive adaptation.', 'Contrast "cognitive convenience" (how the mind experiences it) with "ontological feature" (what is physically true).', 1.4, 0.5, 0.25, true, 0, 'CBSE Class 10 English Communicative'),
('ENG-910-UND-06', 'English Literacy', 'understanding', '9-10', 'advanced', '"The essay posits that modern commodification of art reduces the museum from a temple of contemplative aesthetic communion to a transactional gallery of speculative financial assets." What societal transformation does this critique diagnose?', '[{"text":"A legal requirement that all museums operate as private commercial banks.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"An increase in religious visitors attending art galleries for prayer.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The total obsolescence of oil painting in the face of digital photography.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The subordination of authentic artistic spiritual and cultural value to capitalist investment and elite status display.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Deconstructing critical cultural theory regarding the financialization of art.', 'Contrast "temple of contemplative aesthetic communion" with "transactional gallery of financial assets".', 1.45, 0.7, 0.25, true, 0, 'Cambridge IGCSE Literature in English'),
('ENG-910-UND-07', 'English Literacy', 'understanding', '9-10', 'advanced', '"The cultural theorist argues that nostalgia is not an innocent wistfulness for the past, but an active ideological weapon that rewrites history to legitimize contemporary exclusion." How is nostalgia redefined here?', '[{"text":"As a potent political instrument that curates a mythic golden age to justify current sociopolitical oppression.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"As an incurable neurological disease affecting elderly citizens.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As an artistic aesthetic limited exclusively to Victorian interior decorating.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As an objective chronological method for cataloging museum antiquities.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting critical ideological definitions of collective memory and nostalgia.', 'Look at what nostalgia does politically: "rewrites history to legitimize contemporary exclusion".', 1.5, 0.8, 0.25, true, 0, 'Singapore Secondary 4 Express / GCE O-Level'),
('ENG-910-UND-08', 'English Literacy', 'understanding', '9-10', 'advanced', '"The author describes the desert landscape as ''indifferent rather than cruel,'' insisting that projecting malevolence onto arid dunes is merely human vanity unable to accept a universe that does not care about its survival." What philosophical realization is articulated?', '[{"text":"Cosmic indifference: nature operates by physical laws entirely detached from human moral narratives or emotional desires.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Deserts actively conspire to punish travelers who violate ancient tribal customs.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Human survival is guaranteed in any extreme environment through sheer willpower.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Arid climates are biologically superior to temperate deciduous forests.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing cosmic indifference and the pathetic fallacy in existential literature.', 'Notice: "indifferent rather than cruel", refusing to project malevolence.', 1.5, 0.9, 0.25, true, 0, 'US AP English Language Entry Diagnostic'),
('ENG-910-UND-09', 'English Literacy', 'understanding', '9-10', 'olympiad', '"The structuralist literary critic asserts that the protagonist''s tragedy was not forged in the crucible of his fatal moral flaw (hamartia), but was mechanically predetermined by the socioeconomic constraints of the narrative architecture." How does this interpretation challenge classical Aristotelian poetics?', '[{"text":"It reaffirms that individual ethical choices are the sole driving force of dramatic tragedy.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It displaces individual moral agency and personal fault in favor of systemic, deterministic societal structures.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"It argues that ancient Greek tragedies were written exclusively for comedic entertainment.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It proves that plays must have five acts to maintain dramatic tension.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Contrasting classical individual hamartia with structuralist socioeconomic determinism.', 'Notice the shift from personal moral flaw to narrative/socioeconomic predetermination.', 1.6, 1.1, 0.25, true, 0, 'Singapore Secondary English Olympiad / National Team Trials'),
('ENG-910-UND-10', 'English Literacy', 'understanding', '9-10', 'olympiad', '"The political essayist warns that when totalitarian regimes monopolize language through state-sanctioned euphemisms, they do not merely censor dissenting speech-they dismantle the cognitive conceptual vocabulary required to formulate dissenting thoughts." What profound mechanism of control is identified?', '[{"text":"Enforcing compulsory attendance at patriotic military rallies.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Physical imprisonment of political dissidents in remote penal colonies.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Linguistic determinism: restricting language to preemptively eradicate the mental capacity for critical rebellion.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Banning all import tariffs on foreign consumer electronics.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing Orwellian linguistic hegemony and the constriction of cognitive conceptual horizons.', 'Think about Orwell''s Newspeak: if there are no words for freedom, can people think of freedom?', 1.65, 1.2, 0.25, true, 0, 'Cambridge IGCSE Distinction / IB Middle Years Program'),
('ENG-910-LOC-01', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Food Safety Regulatory Dossier: "Section 4.2: Plasticizer Additive DEHP is strictly prohibited in dairy contact packaging unless the migration coefficient into aqueous food simulants remains below 0.05 mg/dm² over a standardized 10-day test cycle at 40°C." What threshold must DEHP satisfy to be legally permissible?', '[{"text":"Total absence of chemical migration over a 30-day cycle at room temperature.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Migration coefficient strictly below 0.05 mg/dm² under standard 10-day, 40°C conditions.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"A concentration exceeding 0.5 mg/dm² in lipid food simulants.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Thermal stability up to 100°C regardless of packaging contact.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting precise biochemical migration standards and testing conditions from regulatory codes.', 'Check the exact number (0.05 mg/dm²), duration (10 days), and temperature (40°C).', 1.35, 0.2, 0.25, true, 0, 'Cambridge O-Level Informational Text'),
('ENG-910-LOC-02', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Nanotechnology Safety Guidelines: "Carbon nanotube dispersion handling requires a Class II Type B2 biosafety cabinet with 100% exhaust through dual HEPA filtration. Minimum face velocity must be calibrated to 0.53 m/s ± 0.02 m/s." What is the mandated face velocity for the cabinet?', '[{"text":"10 m/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"100 m/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2.0 m/s ± 0.5 m/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"0.53 m/s ± 0.02 m/s","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Scanning occupational health manuals for specific aerodynamic velocity tolerances.', 'Look for "face velocity must be calibrated to".', 1.35, 0.3, 0.25, true, 0, 'Singapore Secondary 3 Express'),
('ENG-910-LOC-03', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Patent Disclosure Statement: "Claim 1: The solar thermoelectric device utilizes bismuth telluride nanowires having an average diameter between 15 nm and 25 nm and an electrical conductivity greater than 1.2 × 10⁵ S/m at 300 K." What is the required diameter range for the nanowires?', '[{"text":"Greater than 1.2 × 10⁵ nm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Between 15 nm and 25 nm","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"300 nm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Exactly 1 nm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting dimensional nanoscale parameters from formal patent claims.', 'Scan for the word "diameter" and note the nanometer range.', 1.4, 0.3, 0.25, true, 0, 'US Common Core Grade 10 Technical Reading'),
('ENG-910-LOC-04', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Clinical Trial Pharmacokinetics: "In Cohort 3, the half-life (t1/2) of mAb-71 was determined to be 18.4 days, while renal clearance averaged 2.1 mL/h. Neutralizing anti-drug antibodies (ADAs) were detected in 3 out of 42 subjects at Day 56." In what fraction of subjects were neutralizing antibodies detected at Day 56?', '[{"text":"All 42 subjects","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"18.4 out of 100 subjects","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2.1 out of 42 subjects","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"3 out of 42 subjects","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Locating specific immunogenicity incidence rates in clinical cohort summaries.', 'Find the sentence mentioning "anti-drug antibodies (ADAs)".', 1.4, 0.4, 0.25, true, 0, 'ICSE Class 10 English Language'),
('ENG-910-LOC-05', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Urban Zoning Statute: "Mixed-Use Commercial Zone C-4 mandates a Floor Area Ratio (FAR) not exceeding 4.5. Maximum building height is capped at 65 meters, with a minimum 8-meter setback from primary road centrelines for all structures exceeding 30 meters." What is the maximum permissible FAR?', '[{"text":"30 meters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"65 meters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"8 meters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Not exceeding 4.5","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Extracting precise regulatory ratios from municipal zoning ordinances.', 'Look directly for "Floor Area Ratio (FAR)".', 1.35, 0.3, 0.25, true, 0, 'CBSE Class 10 English Language'),
('ENG-910-LOC-06', 'English Literacy', 'locatingInformation', '9-10', 'advanced', 'International Environmental Treaty: "Under Annex II of the Minamata Convention on Mercury, parties shall prohibit the manufacturing, import, and export of dental amalgam containing over 50% mercury by mass starting January 1, 2030, unless an exemption for pediatric encapsulation is filed before July 1, 2028." What is the final exemption filing date?', '[{"text":"January 1, 2030","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Before July 1, 2028","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"After 50 years","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"July 1, 2032","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Disentangling prohibition enforcement dates from preliminary exemption filing deadlines.', 'Distinguish between the 2030 prohibition date and the 2028 exemption deadline.', 1.45, 0.6, 0.25, true, 0, 'Cambridge IGCSE English First Language'),
('ENG-910-LOC-07', 'English Literacy', 'locatingInformation', '9-10', 'advanced', 'Deep Space Mission Trajectory: "The gravitational slingshot maneuver around Jupiter will impart an orbital delta-v of 5.8 km/s, adjusting perihelion distance to 0.72 AU. Trajectory correction burn TCM-2 is scheduled for mission elapsed time MET +180 days with a thruster burn duration of 412 seconds." What is the duration of thruster burn TCM-2?', '[{"text":"0.72 AU","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"180 days","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"5.8 km/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"412 seconds","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Scanning orbital mechanics mission timelines for exact engine burn durations.', 'Find the duration paired specifically with "TCM-2".', 1.5, 0.7, 0.25, true, 0, 'Singapore Secondary 4 Express / O-Level'),
('ENG-910-LOC-08', 'English Literacy', 'locatingInformation', '9-10', 'advanced', 'Semiconductor Fabrication Manual: "Photolithography process 7A operates at an extreme ultraviolet (EUV) wavelength of 13.5 nm. Mirror optics must be maintained in a vacuum below 10⁻⁷ Torr, with chamber hydrogen flow stabilized at 25 sccm to mitigate tin debris deposition." What vacuum pressure threshold is required?', '[{"text":"13.5 nm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Below 10⁻⁷ Torr","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"25 sccm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"7A Torr","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating exponential scientific vacuum thresholds in advanced microelectronics literature.', 'Look for the pressure unit "Torr" and the exponential notation.', 1.5, 0.8, 0.25, true, 0, 'US Common Core Grade 10 Technical Evaluation'),
('ENG-910-LOC-09', 'English Literacy', 'locatingInformation', '9-10', 'olympiad', 'Constitutional Court Opinion: "The Appellate Bench held that while Article 19(1)(g) secures the right to practice any trade, reasonable restrictions under Article 19(6) permit mandatory licensing schemes if the licensing fee does not exceed 2% of annual net turnover and an appeal mechanism is adjudicated within 45 days." What is the maximum permitted licensing fee percentage?', '[{"text":"45% of gross profit","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Not exceeding 2% of annual net turnover","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"19% of operating revenue","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"1% of net assets","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating exact statutory financial limitations in complex judicial holdings.', 'Find the percentage limit associated with the "licensing fee".', 1.6, 1, 0.25, true, 0, 'Singapore English Olympiad Senior'),
('ENG-910-LOC-10', 'English Literacy', 'locatingInformation', '9-10', 'olympiad', 'Biomedical Proteomics Paper: "Mass spectrometry analysis identified phosphorylation at serine residue Ser-342 of protein Kinase-B, which increased enzymatic kinase activity by 4.2-fold compared to wild-type, whereas mutation to alanine (Ser342Ala) eliminated phosphorylation and reduced baseline activity by 85%." What effect did the Ser342Ala mutation have on baseline enzymatic activity?', '[{"text":"Doubled phosphorylation rate","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Increased activity by 4.2-fold","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Reduced baseline activity by 85%","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Elevated kinase expression by 342%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting exact quantitative phenotypic outcomes of specific amino acid point mutations.', 'Check specifically what the mutation (Ser342Ala) did, not the original phosphorylation.', 1.65, 1.1, 0.25, true, 0, 'Cambridge IGCSE / GCE O-Level Olympiad Rank')
